class Actor(pygame.sprite.Sprite):
    def update(self, dt):
        self.pos += self.velocity * dt
        self.rect.center = (
            round(self.pos.x), round(self.pos.y)
        )

class Enemy(Actor):
    def __init__(self, name, position, speed=80, hp=1):
        super().__init__(name, position, (44, 40))
        self.velocity.y = speed
        self.hp = hp
        self.max_hp = hp

class Bullet(Actor):
    def update(self, dt):
        super().update(dt)
        if self.rect.bottom < PLAY_AREA.top:
            self.kill()

class FastEnemy(Enemy):
    def __init__(self, name, position):
        super().__init__(name, position, speed=160)

fast = FastEnemy("F01", (200, 100))
fast.update(0.25)
print(fast.pos.y)  # 140.0

class A:
    def act(self): print("A")
class B(A):
    def act(self):
        print("B")
        super().act()
class C(A):
    def act(self):
        print("C")
        super().act()
class D(B, C): pass
D().act()

